# owner: platform
"""Plain text absence notices for parents."""

from typing import Iterable

from rosterkit.models import Mark, Student
from rosterkit.errors import ProjectError


class NoticeError(ProjectError):
    """A notice cannot be written from the given marks."""


def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Short notice: student, count of days, dates.

    Raises NoticeError when a mark belongs to another
    student or when none of the marks are absences.
    """
    entries = list(marks)
    for mark in entries:
        if mark.student_id != student.student_id:
            raise NoticeError(
                f"mark for {mark.student_id} given with "
                f"student {student.student_id}"
            )
    dates = sorted(
        {
            mark.day
            for mark in entries
            if mark.status == "absent"
        }
    )
    if not dates:
        raise NoticeError(
            f"no absences for student {student.student_id}"
        )
    name = f"{student.first_name} {student.last_name}"
    count = len(dates)
    noun = "day" if count == 1 else "days"
    lines = [
        "Dear parent or guardian,",
        "",
        f"{name} was absent for {count} {noun}:"
    ]
    lines.extend(f"- {when.isoformat()}" for when in dates)
    return "\n".join(lines)
